<script setup lang="ts">
import { Head, Link, router } from '@inertiajs/vue3';
import { ref, watch } from 'vue';
import Badge from '@/components/ui/badge/Badge.vue';
import Card from '@/components/ui/card/Card.vue';
import Input from '@/components/ui/input/Input.vue';
import AppLayout from '@/layouts/AppLayout.vue';
import * as inboxRoutes from '@/routes/inbox';
type Conversation = { id: number; status: string; automation_state: string; handled_by_name: string | null; contact: { name: string | null; whatsapp_number: string } };
const props = defineProps<{ conversations: Conversation[]; filters: { search: string; status: string; automationState: string } }>();
const search = ref(props.filters.search); const status = ref(props.filters.status); const automationState = ref(props.filters.automationState);
watch([search, status, automationState], () => router.get(inboxRoutes.index().url, { search: search.value || undefined, status: status.value || undefined, automation_state: automationState.value || undefined }, { preserveState: true, replace: true }));
</script>
<template><Head title="Inbox" /><AppLayout :breadcrumbs="[{ title: 'Inbox', href: inboxRoutes.index() }] "><div class="space-y-6 p-4"><div><h1 class="text-2xl font-semibold">Inbox</h1><p class="text-sm text-muted-foreground">Conversas do WhatsApp preparadas para integração futura.</p></div><div class="grid gap-3 md:grid-cols-3"><Input v-model="search" placeholder="Buscar nome ou WhatsApp" /><select v-model="status" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Todos os status</option><option value="open">Aberta</option><option value="closed">Fechada</option></select><select v-model="automationState" class="h-9 rounded-md border bg-transparent px-3 text-sm"><option value="">Toda automação</option><option value="automated">Automatizada</option><option value="human_paused">Pausada por humano</option></select></div><Card class="overflow-hidden p-0"><div v-if="conversations.length === 0" class="p-8 text-center text-sm text-muted-foreground">Nenhuma conversa encontrada.</div><table v-else class="w-full text-sm"><thead class="border-b bg-muted/50 text-left text-muted-foreground"><tr><th class="p-4">Contato</th><th class="p-4">Status</th><th class="p-4">Automação</th><th class="p-4">Responsável</th></tr></thead><tbody><tr v-for="conversation in conversations" :key="conversation.id" class="border-b last:border-0"><td class="p-4"><Link class="font-medium hover:underline" :href="inboxRoutes.show(conversation.id)">{{ conversation.contact.name || 'Sem nome' }}</Link><div class="text-xs text-muted-foreground">{{ conversation.contact.whatsapp_number }}</div></td><td class="p-4"><Badge :variant="conversation.status === 'open' ? 'default' : 'secondary'">{{ conversation.status === 'open' ? 'Aberta' : 'Fechada' }}</Badge></td><td class="p-4">{{ conversation.automation_state === 'automated' ? 'Automatizada' : 'Pausada' }}</td><td class="p-4">{{ conversation.handled_by_name || '—' }}</td></tr></tbody></table></Card></div></AppLayout></template>
